import 'server-only';

import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

// The full v0.1 schema (spec/data.md). Migrations: src/server/db/migrations/0000_init.sql, 0001_rate_limit_bucket.sql,
// 0002_newsletter.sql (generated by `pnpm db:generate`, applied by `pnpm db:migrate`; 0002 also carries
// hand-written SQL: the ledger-guard trigger, `newsletter_prune_event_ips` and the legacy backfill),
// 0003_newsletter_prune_fix.sql (custom, no DDL diff: `newsletter_prune_event_ips(subscriber, before)`).

const id = () => uuid('id').primaryKey().defaultRandom();
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const siteId = () =>
  uuid('site_id')
    .notNull()
    .references(() => site.id);

// ---------------------------------------------------------------------------------------------
// Newsletter enums (Phase 7, spec/data.md): the CHECK sets, shared with the DTOs' unions.

export const NEWSLETTER_MODES = ['per_post', 'digest', 'manual'] as const;
export const DEFAULT_CONSENT_TEXT = 'One issue a week at most. Unsubscribe in one click; we never share the list.';
export const DEFAULT_CONSENT_VERSION = 'v1';
export const SUBSCRIBER_STATUSES = ['pending', 'confirmed', 'unsubscribed', 'bounced', 'legacy_unconfirmed'] as const;
export const SUBSCRIBER_EVENT_KINDS = [
  'signup',
  'confirmation_sent',
  'confirmed',
  'resubscribed',
  'unsubscribed',
  'bounced',
  'legacy_confirmation_sent',
  'provider_synced',
  'provider_removed',
  'ip_pruned',
] as const;
export const NEWSLETTER_SOURCES = ['footer', 'email_link', 'one_click', 'admin', 'provider', 'webhook', 'migration', 'system'] as const;
export const SUPPRESSION_REASONS = ['unsubscribed', 'bounced', 'complaint', 'admin'] as const;
export const MESSAGE_KINDS = ['confirmation', 'test_issue', 'issue'] as const;
export const MESSAGE_STATUSES = ['sent', 'failed', 'stubbed'] as const;
export const ISSUE_STATUSES = ['draft', 'sending', 'sent', 'failed'] as const;
export const ISSUE_EVENT_KINDS = [
  'created',
  'updated',
  'test_sent',
  'send_requested',
  'provider_created',
  'provider_started',
  'sent',
  'failed',
  'stats_fetched',
  'deleted',
] as const;

// ---------------------------------------------------------------------------------------------

export const site = pgTable('site', {
  id: id(),
  slug: text('slug').notNull().unique('site_slug_unique'),
  brandName: text('brand_name').notNull(),
  wordmark: text('wordmark').notNull(),
  publisherName: text('publisher_name').notNull(),
  tagline: text('tagline').notNull(),
  contactEmail: text('contact_email').notNull(),
  aboutStrap: text('about_strap').notNull(),
  aboutStand: text('about_stand').notNull(),
  aboutBodyMd: text('about_body_md').notNull(),
  socialXUrl: text('social_x_url'),
  socialLinkedinUrl: text('social_linkedin_url'),
  timezone: text('timezone').notNull().default('Asia/Kolkata'),
  // Phase 7 (0002_newsletter) — Admin → Site → Newsletter (spec/capabilities/newsletter-issues.md).
  newsletterMode: text('newsletter_mode', { enum: NEWSLETTER_MODES }).notNull().default('manual'),
  newsletterAutoSend: boolean('newsletter_auto_send').notNull().default(false),
  newsletterDigestDays: integer('newsletter_digest_days').notNull().default(7),
  newsletterDigestPosts: integer('newsletter_digest_posts').notNull().default(3),
  newsletterConsentText: text('newsletter_consent_text').notNull().default(DEFAULT_CONSENT_TEXT),
  newsletterConsentVersion: text('newsletter_consent_version').notNull().default(DEFAULT_CONSENT_VERSION),
  newsletterModeSetAt: timestamp('newsletter_mode_set_at', { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  check('site_newsletter_mode_check', sql`${t.newsletterMode} in ('per_post', 'digest', 'manual')`),
  check('site_newsletter_digest_days_check', sql`${t.newsletterDigestDays} between 1 and 60`),
  check('site_newsletter_digest_posts_check', sql`${t.newsletterDigestPosts} between 1 and 20`),
]);

export const appUser = pgTable(
  'app_user',
  {
    id: id(),
    siteId: siteId(),
    email: text('email').notNull(),
    displayName: text('display_name').notNull(),
    passwordHash: text('password_hash').notNull(),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    disabledAt: timestamp('disabled_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('app_user_site_email_unique').on(t.siteId, t.email)],
);

export const session = pgTable(
  'session',
  {
    id: id(),
    siteId: siteId(),
    userId: uuid('user_id')
      .notNull()
      .references(() => appUser.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique('session_token_hash_unique'),
    createdAt: createdAt(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    userAgent: text('user_agent'),
    ip: text('ip'),
  },
  (t) => [index('session_user_idx').on(t.userId)],
);

export const ARTICLE_STATUSES = ['draft', 'submitted', 'approved', 'published'] as const;

export const article = pgTable(
  'article',
  {
    id: id(),
    siteId: siteId(),
    slug: text('slug').notNull(),
    slugIsCustom: boolean('slug_is_custom').notNull().default(false),
    status: text('status', { enum: ARTICLE_STATUSES }).notNull().default('draft'),
    topic: text('topic').notNull().default(''),
    bylineName: text('byline_name').notNull(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => appUser.id),
    currentRevisionId: uuid('current_revision_id').references((): AnyPgColumn => articleRevision.id, {
      onDelete: 'set null',
    }),
    publishedRevisionId: uuid('published_revision_id').references((): AnyPgColumn => articleRevision.id, {
      onDelete: 'set null',
    }),
    isFeatured: boolean('is_featured').notNull().default(false),
    featuredRank: integer('featured_rank'),
    inProgress: boolean('in_progress').notNull().default(false),
    firstPublishedAt: timestamp('first_published_at', { withTimezone: true }),
    lastPublishedAt: timestamp('last_published_at', { withTimezone: true }),
    contentUpdatedAt: timestamp('content_updated_at', { withTimezone: true }),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    approvedAt: timestamp('approved_at', { withTimezone: true }),
    submittedBy: uuid('submitted_by').references(() => appUser.id),
    approvedBy: uuid('approved_by').references(() => appUser.id),
    correctionsNoteMd: text('corrections_note_md'),
    correctionsUpdatedAt: timestamp('corrections_updated_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('article_site_slug_unique').on(t.siteId, t.slug),
    index('article_site_status_published_idx').on(t.siteId, t.status, t.firstPublishedAt.desc()),
    index('article_site_featured_idx').on(t.siteId, t.isFeatured, t.featuredRank),
    check('article_status_check', sql`${t.status} in ('draft', 'submitted', 'approved', 'published')`),
  ],
);

export const articleRevision = pgTable(
  'article_revision',
  {
    id: id(),
    siteId: siteId(),
    articleId: uuid('article_id')
      .notNull()
      .references((): AnyPgColumn => article.id, { onDelete: 'cascade' }),
    number: integer('number').notNull(),
    title: text('title').notNull(),
    dek: text('dek').notNull().default(''),
    bodyMd: text('body_md').notNull(),
    bodyFingerprint: text('body_fingerprint').notNull(),
    paragraphsFingerprint: text('paragraphs_fingerprint').notNull(),
    sentencesFingerprint: text('sentences_fingerprint').notNull(),
    wordCount: integer('word_count').notNull(),
    eligibleSentenceCount: integer('eligible_sentence_count').notNull(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => appUser.id),
    restoredFromRevisionId: uuid('restored_from_revision_id').references((): AnyPgColumn => articleRevision.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('article_revision_article_number_unique').on(t.articleId, t.number)],
);

export const articleFormat = pgTable(
  'article_format',
  {
    id: id(),
    siteId: siteId(),
    articleId: uuid('article_id')
      .notNull()
      .references(() => article.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    draftPayload: jsonb('draft_payload'),
    draftRevisionId: uuid('draft_revision_id').references(() => articleRevision.id),
    draftFingerprint: text('draft_fingerprint'),
    draftUpdatedBy: uuid('draft_updated_by').references(() => appUser.id),
    draftUpdatedAt: timestamp('draft_updated_at', { withTimezone: true }),
    publishedPayload: jsonb('published_payload'),
    publishedRevisionId: uuid('published_revision_id').references(() => articleRevision.id),
    publishedFingerprint: text('published_fingerprint'),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('article_format_article_kind_unique').on(t.articleId, t.kind)],
);

export const GENERATION_STATUSES = ['running', 'succeeded', 'failed'] as const;

export const aiGeneration = pgTable(
  'ai_generation',
  {
    id: id(),
    siteId: siteId(),
    articleId: uuid('article_id')
      .notNull()
      .references(() => article.id, { onDelete: 'cascade' }),
    revisionId: uuid('revision_id')
      .notNull()
      .references(() => articleRevision.id),
    formatKind: text('format_kind').notNull(),
    task: text('task').notNull(),
    status: text('status', { enum: GENERATION_STATUSES }).notNull(),
    requestedBy: uuid('requested_by')
      .notNull()
      .references(() => appUser.id),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    model: text('model').notNull(),
    promptVersion: text('prompt_version').notNull(),
    inputFingerprint: text('input_fingerprint').notNull(),
    sentenceCount: integer('sentence_count').notNull(),
    boundMin: integer('bound_min').notNull(),
    boundMax: integer('bound_max').notNull(),
    attempts: integer('attempts').notNull().default(0),
    promptTokens: integer('prompt_tokens'),
    completionTokens: integer('completion_tokens'),
    totalTokens: integer('total_tokens'),
    costUsd: numeric('cost_usd', { precision: 12, scale: 6, mode: 'number' }),
    latencyMs: integer('latency_ms'),
    providerGenerationIds: text('provider_generation_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    output: jsonb('output'),
    errorCode: text('error_code'),
    errorMessage: text('error_message'),
    createdAt: createdAt(),
  },
  (t) => [
    index('ai_generation_site_started_idx').on(t.siteId, t.startedAt.desc()),
    index('ai_generation_article_started_idx').on(t.articleId, t.startedAt.desc()),
    check('ai_generation_status_check', sql`${t.status} in ('running', 'succeeded', 'failed')`),
  ],
);

/**
 * The owned list (Phase 7, spec/capabilities/newsletter-list.md; widened by 0002_newsletter). `status`
 * is the current state; the history lives in newsletter_subscriber_event, the do-not-send proof in
 * newsletter_suppression. Tokens are stored hashed only.
 */
export const newsletterSubscriber = pgTable(
  'newsletter_subscriber',
  {
    id: id(),
    siteId: siteId(),
    email: text('email').notNull(),
    name: text('name'),
    status: text('status', { enum: SUBSCRIBER_STATUSES }).notNull().default('pending'),
    source: text('source').notNull().default('footer'),
    signupSourceUrl: text('signup_source_url'),
    signupIp: text('signup_ip'),
    signupUserAgent: text('signup_user_agent'),
    consentText: text('consent_text'),
    consentVersion: text('consent_version'),
    consentedAt: timestamp('consented_at', { withTimezone: true }),
    confirmTokenHash: text('confirm_token_hash'),
    confirmTokenExpiresAt: timestamp('confirm_token_expires_at', { withTimezone: true }),
    confirmationSentCount: integer('confirmation_sent_count').notNull().default(0),
    legacyConfirmationSentAt: timestamp('legacy_confirmation_sent_at', { withTimezone: true }),
    confirmedAt: timestamp('confirmed_at', { withTimezone: true }),
    confirmedIp: text('confirmed_ip'),
    confirmedUserAgent: text('confirmed_user_agent'),
    unsubscribedAt: timestamp('unsubscribed_at', { withTimezone: true }),
    providerId: text('provider_id'),
    providerSyncedAt: timestamp('provider_synced_at', { withTimezone: true }),
    ipPrunedAt: timestamp('ip_pruned_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('newsletter_subscriber_site_email_unique').on(t.siteId, t.email),
    uniqueIndex('newsletter_subscriber_confirm_token_unique')
      .on(t.confirmTokenHash)
      .where(sql`${t.confirmTokenHash} is not null`),
    index('newsletter_subscriber_site_status_idx').on(t.siteId, t.status),
    index('newsletter_subscriber_site_confirmed_idx').on(t.siteId, t.confirmedAt.desc()),
    check(
      'newsletter_subscriber_status_check',
      sql`${t.status} in ('pending', 'confirmed', 'unsubscribed', 'bounced', 'legacy_unconfirmed')`,
    ),
  ],
);

/** Append-only (trigger `newsletter_ledger_guard`): one row per thing that happened to a subscriber. */
export const newsletterSubscriberEvent = pgTable(
  'newsletter_subscriber_event',
  {
    id: id(),
    siteId: siteId(),
    subscriberId: uuid('subscriber_id')
      .notNull()
      .references(() => newsletterSubscriber.id, { onDelete: 'restrict' }),
    email: text('email').notNull(),
    kind: text('kind', { enum: SUBSCRIBER_EVENT_KINDS }).notNull(),
    source: text('source', { enum: NEWSLETTER_SOURCES }).notNull(),
    actorUserId: uuid('actor_user_id').references(() => appUser.id),
    ip: text('ip'),
    userAgent: text('user_agent'),
    details: jsonb('details').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('newsletter_subscriber_event_subscriber_idx').on(t.subscriberId, t.createdAt),
    index('newsletter_subscriber_event_site_created_idx').on(t.siteId, t.createdAt.desc()),
    check(
      'newsletter_subscriber_event_kind_check',
      sql`${t.kind} in ('signup', 'confirmation_sent', 'confirmed', 'resubscribed', 'unsubscribed', 'bounced', 'legacy_confirmation_sent', 'provider_synced', 'provider_removed', 'ip_pruned')`,
    ),
    check(
      'newsletter_subscriber_event_source_check',
      sql`${t.source} in ('footer', 'email_link', 'one_click', 'admin', 'provider', 'webhook', 'migration', 'system')`,
    ),
  ],
);

/** Append-only, never deleted: the permanent do-not-send ledger. */
export const newsletterSuppression = pgTable(
  'newsletter_suppression',
  {
    id: id(),
    siteId: siteId(),
    subscriberId: uuid('subscriber_id')
      .notNull()
      .references(() => newsletterSubscriber.id, { onDelete: 'restrict' }),
    email: text('email').notNull(),
    reason: text('reason', { enum: SUPPRESSION_REASONS }).notNull(),
    source: text('source', { enum: NEWSLETTER_SOURCES }).notNull(),
    details: jsonb('details').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('newsletter_suppression_site_email_idx').on(t.siteId, t.email, t.createdAt.desc()),
    check('newsletter_suppression_reason_check', sql`${t.reason} in ('unsubscribed', 'bounced', 'complaint', 'admin')`),
    check(
      'newsletter_suppression_source_check',
      sql`${t.source} in ('footer', 'email_link', 'one_click', 'admin', 'provider', 'webhook', 'migration', 'system')`,
    ),
  ],
);

/** One issue (spec/capabilities/newsletter-issues.md). */
export const newsletterIssue = pgTable(
  'newsletter_issue',
  {
    id: id(),
    siteId: siteId(),
    number: integer('number').notNull(),
    status: text('status', { enum: ISSUE_STATUSES }).notNull().default('draft'),
    origin: text('origin', { enum: NEWSLETTER_MODES }).notNull(),
    title: text('title').notNull(),
    introMd: text('intro_md').notNull().default(''),
    posts: jsonb('posts').notNull(),
    articleIds: uuid('article_ids').array().notNull(),
    renderedHtml: text('rendered_html'),
    renderedText: text('rendered_text'),
    providerCampaignId: text('provider_campaign_id'),
    recipientCount: integer('recipient_count'),
    stats: jsonb('stats'),
    lastError: text('last_error'),
    createdBy: uuid('created_by').references(() => appUser.id),
    sentBy: uuid('sent_by').references(() => appUser.id),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('newsletter_issue_site_number_unique').on(t.siteId, t.number),
    index('newsletter_issue_site_created_idx').on(t.siteId, t.createdAt.desc()),
    index('newsletter_issue_site_status_idx').on(t.siteId, t.status),
    check('newsletter_issue_status_check', sql`${t.status} in ('draft', 'sending', 'sent', 'failed')`),
    check('newsletter_issue_origin_check', sql`${t.origin} in ('per_post', 'digest', 'manual')`),
  ],
);

/** The send log — append-only (same trigger guard; a draft's events go with it on delete). */
export const newsletterIssueEvent = pgTable(
  'newsletter_issue_event',
  {
    id: id(),
    siteId: siteId(),
    issueId: uuid('issue_id')
      .notNull()
      .references(() => newsletterIssue.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ISSUE_EVENT_KINDS }).notNull(),
    actorUserId: uuid('actor_user_id').references(() => appUser.id),
    details: jsonb('details').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('newsletter_issue_event_issue_idx').on(t.issueId, t.createdAt),
    check(
      'newsletter_issue_event_kind_check',
      sql`${t.kind} in ('created', 'updated', 'test_sent', 'send_requested', 'provider_created', 'provider_started', 'sent', 'failed', 'stats_fetched', 'deleted')`,
    ),
  ],
);

/** Every transactional message blog0 composed (+ the stub sender's deliveries). With the stub transport the row is the delivery. */
export const newsletterMessage = pgTable(
  'newsletter_message',
  {
    id: id(),
    siteId: siteId(),
    kind: text('kind', { enum: MESSAGE_KINDS }).notNull(),
    subscriberId: uuid('subscriber_id').references(() => newsletterSubscriber.id, { onDelete: 'restrict' }),
    issueId: uuid('issue_id').references(() => newsletterIssue.id, { onDelete: 'restrict' }),
    toEmail: text('to_email').notNull(),
    subject: text('subject').notNull(),
    html: text('html').notNull(),
    text: text('text').notNull(),
    transport: text('transport').notNull(),
    status: text('status', { enum: MESSAGE_STATUSES }).notNull(),
    providerMessageId: text('provider_message_id'),
    error: text('error'),
    createdAt: createdAt(),
  },
  (t) => [
    index('newsletter_message_site_created_idx').on(t.siteId, t.createdAt.desc()),
    index('newsletter_message_subscriber_created_idx').on(t.subscriberId, t.createdAt.desc()),
    index('newsletter_message_issue_idx').on(t.issueId),
    check('newsletter_message_kind_check', sql`${t.kind} in ('confirmation', 'test_issue', 'issue')`),
    check('newsletter_message_status_check', sql`${t.status} in ('sent', 'failed', 'stubbed')`),
  ],
);

export const MEDIA_KINDS = ['image', 'audio'] as const;

export const mediaAsset = pgTable(
  'media_asset',
  {
    id: id(),
    siteId: siteId(),
    kind: text('kind', { enum: MEDIA_KINDS }).notNull(),
    storageKey: text('storage_key').notNull().unique('media_asset_storage_key_unique'),
    originalFilename: text('original_filename').notNull(),
    mimeType: text('mime_type').notNull(),
    byteSize: bigint('byte_size', { mode: 'number' }).notNull(),
    sha256: text('sha256').notNull(),
    durationSec: numeric('duration_sec', { precision: 10, scale: 3, mode: 'number' }),
    width: integer('width'),
    height: integer('height'),
    articleId: uuid('article_id').references(() => article.id, { onDelete: 'set null' }),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => appUser.id),
    createdAt: createdAt(),
  },
  (t) => [check('media_asset_kind_check', sql`${t.kind} in ('image', 'audio')`)],
);

/**
 * Phase 5 (migration 0001_rate_limit_bucket): one fixed throttle window per (site, scope, key) —
 * capability abuse-protection, spec/data.md → rate_limit_bucket. `key_hash` is sha256 hex of the raw
 * key (never the email/IP itself); rows are ephemeral (pruned once expired, not backed up).
 */
export const rateLimitBucket = pgTable(
  'rate_limit_bucket',
  {
    siteId: uuid('site_id')
      .notNull()
      .references(() => site.id, { onDelete: 'cascade' }),
    scope: text('scope').notNull(),
    keyHash: text('key_hash').notNull(),
    windowStart: timestamp('window_start', { withTimezone: true }).notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    count: integer('count').notNull().default(0),
  },
  (t) => [
    primaryKey({ name: 'rate_limit_bucket_pk', columns: [t.siteId, t.scope, t.keyHash, t.windowStart] }),
    index('rate_limit_bucket_expires_idx').on(t.expiresAt),
    check('rate_limit_bucket_count_check', sql`${t.count} >= 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Row types (inferred) — shared by every service.

export type SiteRow = typeof site.$inferSelect;
export type NewSiteRow = typeof site.$inferInsert;
export type AppUserRow = typeof appUser.$inferSelect;
export type SessionRow = typeof session.$inferSelect;
export type ArticleRow = typeof article.$inferSelect;
export type RevisionRow = typeof articleRevision.$inferSelect;
export type ArticleFormatRow = typeof articleFormat.$inferSelect;
export type AiGenerationRow = typeof aiGeneration.$inferSelect;
export type NewsletterSubscriberRow = typeof newsletterSubscriber.$inferSelect;
export type NewsletterSubscriberEventRow = typeof newsletterSubscriberEvent.$inferSelect;
export type NewsletterSuppressionRow = typeof newsletterSuppression.$inferSelect;
export type NewsletterMessageRow = typeof newsletterMessage.$inferSelect;
export type NewsletterIssueRow = typeof newsletterIssue.$inferSelect;
export type NewsletterIssueEventRow = typeof newsletterIssueEvent.$inferSelect;
export type MediaAssetRow = typeof mediaAsset.$inferSelect;
export type RateLimitBucketRow = typeof rateLimitBucket.$inferSelect;

/** Every table, children first — the order resetDb() truncates in. */
export const ALL_TABLE_NAMES = [
  'rate_limit_bucket',
  'newsletter_message',
  'newsletter_issue_event',
  'newsletter_issue',
  'newsletter_subscriber_event',
  'newsletter_suppression',
  'media_asset',
  'newsletter_subscriber',
  'ai_generation',
  'article_format',
  'article_revision',
  'article',
  'session',
  'app_user',
  'site',
] as const;
